<?php
declare(strict_types=1);

/** Shared read-only TG liability balances in their original invoice currencies. */
function tgl_paid(array $store,string $id,string $asOf=''):float{$n=0.0;foreach((array)($store['tgBankTransactions']??[]) as $x){if(!is_array($x)||($x['kind']??'')!=='Payment'||($asOf!==''&&(string)($x['date']??'')>$asOf))continue;if(!empty($x['liabilityAllocations'])){foreach($x['liabilityAllocations'] as $a)if(($a['id']??'')===$id)$n+=(float)($a['amountNative']??0);}elseif(($x['sourceLiabilityId']??'')===$id)$n+=(float)($x['amountNative']??0);}return round($n,2);}
function tgl_supplier_rows(array $store):array{$out=[];foreach((array)($store['tgLiabilities']??[]) as $x){if(!is_array($x))continue;$orig=(float)($x['nativeAmount']??0);$paid=tgl_paid($store,(string)$x['id']);$open=round($orig-$paid,2);$rate=(float)($x['currentCarryingRate']??$x['recognitionRate']??0);$out[]=array_merge($x,['source'=>'Accounts Supplier / Service Bill','originalNative'=>$orig,'paidNative'=>$paid,'outstandingNative'=>max(0,$open),'currentCarryingRate'=>$rate,'outstandingAed'=>round(max(0,$open)*$rate,2),'status'=>$open>.0001?'Open':'Settled']);}return $out;}
function tgl_intercompany_rows(array $store):array{$out=[];foreach((array)($store['exportCandidates']??[]) as $c){if(!is_array($c)||($c['entity']??'')!=='TG'||($c['candidateType']??'')!=='TG_INTERCOMPANY_PAYABLE'||empty($c['journalId']))continue;$orig=(float)($c['transactionAmount']??0);$paid=tgl_paid($store,(string)$c['id']);$open=round($orig-$paid,2);$rate=(float)($c['currentCarryingRate']??$c['functionalRate']??0);$m=is_array($c['meta']??null)?$c['meta']:[];$out[]=['id'=>(string)$c['id'],'source'=>'Exports — TG Intercompany','date'=>(string)($c['recognitionDate']??$c['suggestedRecognitionDate']??''),'dueDate'=>'','counterparty'=>(string)($c['counterparty']??'TTI'),'reference'=>(string)($c['reference']??$c['sourceKey']??''),'currency'=>(string)($c['transactionCurrency']??'USD'),'originalNative'=>$orig,'paidNative'=>$paid,'outstandingNative'=>max(0,$open),'currentCarryingRate'=>$rate,'outstandingAed'=>round(max(0,$open)*$rate,2),'payableAccount'=>'2500','debitAccount'=>(string)($c['costAccount']??''),'journalId'=>(string)$c['journalId'],'contractRef'=>(string)($m['contractRef']??''),'product'=>(string)($m['product']??''),'status'=>$open>.0001?'Open':'Settled'];}return $out;}
